import test_go_on_property as T
from echo_sync import fast_text as F
from echo_sync.classifier import QUESTION, analyze, strip_fillers
from echo_sync.settings import CALL_SETTINGS


def ends_n(heard, portion, n, restore=False):
    try:
        left, right = F._atoms(heard), F._atoms(portion)
        if restore:
            left = F._last_word_restored(left, right)
        if F._changed(left, right) or F._runs(left, right) is None:
            return False
        said, key = F._ends(left, right), F._ends(right, right)[-n:]
        return bool(key) and said is not None and said[-len(key):] == key and F._nots_agree(left, right)
    except Exception:
        return False


def isq(h, p):
    said = strip_fillers(h, CALL_SETTINGS)
    state = {'chunks': ['Первая часть ответа.', p], 'chunk_index': 1, 'revision': 1}
    return analyze(h, state, [], CALL_SETTINGS).kind == QUESTION


def test_dbg():
    out = []
    kinds = ['verbatim', 'a word lost', 'own words, its end', 'numbers in words', 'a number in pairs', 'two parts', 'a part and a pause', 'another question', 'a number changed', 'a number changed, in words', '«не» lost', '«не» put in', 'the ear']
    V = {'base': lambda h, p: F.most_said(strip_fillers(h, CALL_SETTINGS), p) or F.ends_like(strip_fillers(h, CALL_SETTINGS), p),
         'e2': lambda h, p: ends_n(strip_fillers(h, CALL_SETTINGS), p, 2),
         'e1': lambda h, p: ends_n(strip_fillers(h, CALL_SETTINGS), p, 1),
         'e1r': lambda h, p: ends_n(strip_fillers(h, CALL_SETTINGS), p, 1, True),
         'e2r': lambda h, p: ends_n(strip_fillers(h, CALL_SETTINGS), p, 2, True)}
    ex = {}
    for k in kinds:
        cs = [(h, p) for w, kk, h, p in T.CASES if kk == k]
        row = []
        for name, f in V.items():
            n = sum(1 for h, p in cs if not isq(h, p) and f(h, p))
            row.append('%s=%d' % (name, n))
            if name in ('e1r',) and k in ('numbers in words', 'a word lost', 'a part and a pause', 'another question'):
                bad = [(h, p) for h, p in cs if (not isq(h, p) and f(h, p)) != (k in ('another question', 'a part and a pause') and False or k in ('numbers in words', 'a word lost'))]
                ex[k] = bad[:4]
        out.append('%s/%d: %s' % (k, len(cs), ' '.join(row)))
    raise AssertionError('DBG\n' + '\n'.join(out) + '\n' + repr(ex))
